const now = $now.setZone('Asia/Seoul');
const runDt = now.minus({ minutes: now.minute % 5 }).set({ second: 0, millisecond: 0 });
const hasKey = String($env.GITS_API_KEY ?? '').trim().length > 0;

return [{
  json: {
    runDt: runDt.toFormat('yyyy-LL-dd HH:mm:ss'),
    hasKey: hasKey ? 1 : 0,
  },
}];

const links = $input.all()
  .map((item) => item.json)
  .filter((row) => row.TRAFFIC_LINK_ID != null && row.LINK_ID != null && row.ROUTE_ID != null)
  .map((row) => ({
    trafficLinkId: Number(row.TRAFFIC_LINK_ID),
    linkId: String(row.LINK_ID),
    routeId: String(row.ROUTE_ID),
  }));
const collectRunId = Number($('회차 행 조회').first().json.COLLECT_RUN_ID);

return [{
  json: {
    collectRunId,
    runDt: $('회차 시각 계산').first().json.runDt,
    hasLinks: links.length > 0,
    linkCount: links.length,
    links,
    errorMessage: '링크 목록 비어 있음 — 링크 목록 만들기를 먼저 실행',
  },
}];

const context = $input.first().json;
const byRoute = new Map();

for (const link of context.links) {
  if (!byRoute.has(link.routeId)) byRoute.set(link.routeId, []);
  byRoute.get(link.routeId).push(link);
}

return [...byRoute.entries()].map(([routeId, links]) => ({
  json: { routeId, links },
}));

function decodeXml(value) {
  return value
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, String.fromCharCode(34))
    .replace(/&apos;/g, String.fromCharCode(39))
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)))
    .replace(/&amp;/g, '&');
}

function tagValue(xml, tagName) {
  const match = xml.match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
  return match ? decodeXml(match[1].replace(/^\s*<!\[CDATA\[/, '').replace(/\]\]>\s*$/, '').trim()) : null;
}

function findJsonValue(value, key) {
  if (Array.isArray(value)) {
    for (const child of value) {
      const found = findJsonValue(child, key);
      if (found != null) return found;
    }
    return null;
  }
  if (!value || typeof value !== 'object') return null;
  if (Object.prototype.hasOwnProperty.call(value, key) && value[key] != null) return value[key];
  for (const child of Object.values(value)) {
    const found = findJsonValue(child, key);
    if (found != null) return found;
  }
  return null;
}

function jsonRecords(value, anchor) {
  const records = [];
  function visit(node) {
    if (Array.isArray(node)) {
      for (const child of node) visit(child);
      return;
    }
    if (!node || typeof node !== 'object') return;
    let childHasRecord = false;
    for (const child of Object.values(node)) {
      const before = records.length;
      visit(child);
      if (records.length > before) childHasRecord = true;
    }
    if (!childHasRecord && Object.prototype.hasOwnProperty.call(node, anchor)) records.push(node);
  }
  visit(value);
  return records;
}

function xmlRecords(xml, anchor, fields) {
  const root = { children: [] };
  const stack = [root];
  const pattern = /<\/?([A-Za-z_][\w:.-]*)(?:\s[^>]*)?\s*\/?\s*>/g;
  let match;
  while ((match = pattern.exec(xml)) !== null) {
    const token = match[0];
    const name = match[1].split(':').pop();
    if (token.startsWith('</')) {
      for (let index = stack.length - 1; index > 0; index -= 1) {
        if (stack[index].name === name) {
          const node = stack[index];
          node.inner = xml.slice(node.contentStart, match.index);
          stack.length = index;
          break;
        }
      }
    } else if (!token.endsWith('/>')) {
      const node = { name, contentStart: pattern.lastIndex, inner: '', children: [] };
      stack[stack.length - 1].children.push(node);
      stack.push(node);
    }
  }
  function qualifies(node) {
    if (!node.inner || tagValue(node.inner, anchor) == null) return false;
    return fields.some((field) => field !== anchor && tagValue(node.inner, field) != null);
  }
  const records = [];
  function collect(node) {
    const qualifiedChildren = node.children.filter(qualifies);
    if (qualifies(node) && qualifiedChildren.length === 0) {
      records.push(node.inner);
      return;
    }
    for (const child of node.children) collect(child);
  }
  for (const child of root.children) collect(child);
  return records;
}

function nonNegativeRounded(value) {
  const text = value == null ? null : String(value).trim();
  if (text == null || !/^\d+(\.\d+)?$/.test(text)) return null;
  const parsed = Math.round(Number(text));
  return Number.isSafeInteger(parsed) && parsed >= 0 ? parsed : null;
}

function parseCollDate(value) {
  const text = value == null ? '' : String(value).trim();
  let match = text.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/);
  if (match) return `${match[1]}-${match[2]}-${match[3]} ${match[4]}:${match[5]}:${match[6]}`;
  // 실제 응답은 '2026-11-11 16:05:00.0'처럼 소수 초가 붙는다.
  match = text.match(/^(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?$/);
  return match ? `${match[1]} ${match[2]}:${match[3]}:${match[4] || '00'}` : null;
}

const results = [];
const rows = [];
for (const item of $input.all()) {
  const response = item.json;
  const status = Number(response.statusCode);
  const body = typeof response.body === 'string' ? response.body : '';
  let parsedJson = null;
  try { parsedJson = JSON.parse(body); } catch {}
  const headerCdRaw = parsedJson == null ? tagValue(body, 'headerCd') : findJsonValue(parsedJson, 'headerCd');
  const headerCd = headerCdRaw == null ? null : String(headerCdRaw).trim();

  if (status !== 200 || headerCd !== '0') {
    const reason = status !== 200
      ? (Number.isInteger(status) ? `HTTP_${status}` : 'HTTP_ERROR')
      : headerCd && /^[A-Za-z0-9_-]{1,50}$/.test(headerCd) ? `GITS_${headerCd}` : 'INVALID_DATA';
    for (const link of response.links || []) results.push({ trafficLinkId: link.trafficLinkId, ok: false, reason });
    continue;
  }

  const records = parsedJson == null
    ? xmlRecords(body, 'linkId', ['linkId', 'spd', 'trvlTime', 'collDate'])
    : jsonRecords(parsedJson, 'linkId');
  const byLinkId = new Map();
  for (const record of records) {
    const get = (field) => typeof record === 'string' ? tagValue(record, field) : findJsonValue(record, field);
    const linkId = get('linkId');
    if (linkId != null && !byLinkId.has(String(linkId))) byLinkId.set(String(linkId), { get });
  }

  for (const link of response.links || []) {
    const record = byLinkId.get(link.linkId);
    if (!record) {
      results.push({ trafficLinkId: link.trafficLinkId, ok: false, reason: 'LINK_NOT_IN_RESPONSE' });
      continue;
    }
    const roundedSpeed = nonNegativeRounded(record.get('spd'));
    // 0~300km/h 밖은 비정상 값으로 본다(SPEED_KMH는 SMALLINT).
    const speed = roundedSpeed !== null && roundedSpeed <= 300 ? roundedSpeed : null;
    const travelSec = nonNegativeRounded(record.get('trvlTime'));
    if (speed == null || travelSec == null) {
      results.push({ trafficLinkId: link.trafficLinkId, ok: false, reason: 'INVALID_DATA' });
      continue;
    }
    rows.push({
      trafficLinkId: link.trafficLinkId,
      sourceCollectedDt: parseCollDate(record.get('collDate')),
      speed,
      travelSec,
    });
    results.push({ trafficLinkId: link.trafficLinkId, ok: true, reason: null });
  }
}

return [{ json: { rows, results } }];

const results = $('응답 판정').first().json.results || [];
const reasonCounts = {};

for (const result of results) {
  if (result.ok) continue;
  const reason = result.reason || 'UNKNOWN';
  reasonCounts[reason] = (reasonCounts[reason] || 0) + 1;
}

const dbFailed = $input.all().some((item) => item.json.error != null);
if (dbFailed) reasonCounts.DB_INSERT_FAILED = (reasonCounts.DB_INSERT_FAILED || 0) + 1;

const errorSummary = Object.entries(reasonCounts)
  .sort(([left], [right]) => left.localeCompare(right))
  .map(([reason, count]) => `${reason}: ${count}`)
  .join('; ')
  .slice(0, 500);

return [{
  json: {
    collectRunId: $('링크 목록 준비').first().json.collectRunId,
    linkCount: $('링크 목록 준비').first().json.linkCount,
    errorMessageParam: errorSummary || '__NULL__',
  },
}];
